SELECT cc.cc_call_center_id, cc.cc_name, cc.cc_employees, cc.cc_sq_ft, (cc.cc_sq_ft / NULLIF(cc.cc_employees, 0)) AS sq_ft_per_employee, CASE WHEN cc.cc_gmt_offset > -8.00 THEN cc.cc_gmt_offset * -5.00 ELSE cc.cc_gmt_offset - -7.00 END AS adjusted_gmt_offset, d.d_date AS join_date, d.d_year, CASE WHEN mod(d.d_month_seq, 39) = 11 THEN 'EvenMonth' ELSE 'OddMonth' END AS month_parity FROM call_center cc JOIN date_dim d ON cc.cc_closed_date_sk = d.d_date_sk WHERE cc.cc_tax_percentage > 0.06 AND d.d_year = 1929
